class Solution {
public:
    vector<string> letterCasePermutation(string s) {
        vector<string> res;
        string path = "";
        auto backtrack = [&](auto& self, int i) -> void {
            if (i == (int)s.size()) {
                res.push_back(path);
                return;
            }
            char ch = s[i];
            if (isalpha(ch)) {
                path.push_back(tolower(ch));
                self(self, i + 1);
                path.pop_back();
                path.push_back(toupper(ch));
                self(self, i + 1);
                path.pop_back();
            } else {
                path.push_back(ch);
                self(self, i + 1);
                path.pop_back();
            }
        };
        backtrack(backtrack, 0);
        return res;
    }
};

class Solution {
    public List<String> letterCasePermutation(String s) {
        List<String> res = new ArrayList<>();
        char[] chars = s.toCharArray();
        backtrack(0, chars, res);
        return res;
    }

    private void backtrack(int i, char[] chars, List<String> res) {
        if (i == chars.length) {
            res.add(new String(chars));
            return;
        }
        char ch = chars[i];
        if (Character.isLetter(ch)) {
            chars[i] = Character.toLowerCase(ch);
            backtrack(i + 1, chars, res);
            chars[i] = Character.toUpperCase(ch);
            backtrack(i + 1, chars, res);
            chars[i] = ch;
        } else {
            backtrack(i + 1, chars, res);
        }
    }
}

var letterCasePermutation = function(s) {
    const res = [];
    const n = s.length;
    const backtrack = (i, path) => {
        if (i === n) {
            res.push(path.join(''));
            return;
        }
        const ch = s[i];
        if (/[a-zA-Z]/.test(ch)) {
            path.push(ch.toLowerCase());
            backtrack(i + 1, path);
            path.pop();
            path.push(ch.toUpperCase());
            backtrack(i + 1, path);
            path.pop();
        } else {
            path.push(ch);
            backtrack(i + 1, path);
            path.pop();
        }
    };
    backtrack(0, []);
    return res;
};
